"// ---- svg builders ----",
"function colChart(mo,series,names,colors){ // series: mi->name->v",
" var W=Math.max(600,mo.length*54+46),H=236,PB=34,PL=46,mx=1;",
" var mv=mo.map(function(mi){var s=0;names.forEach(function(g){s+=Math.max(0,(series[mi]||{})[g]||0);});if(s>mx)mx=s;return s;});",
" var sv='<svg width=\"100%\" viewBox=\"0 0 '+W+' '+H+'\" xmlns=\"http://www.w3.org/2000/svg\">';",
" [0.25,0.5,0.75,1].forEach(function(f){var y=(H-PB)*(1-f)+14;sv+='<line x1=\"'+PL+'\" y1=\"'+y+'\" x2=\"'+W+'\" y2=\"'+y+'\" stroke=\"#EDF1F7\"/><text x=\"'+(PL-6)+'\" y=\"'+(y+3)+'\" font-size=\"9\" fill=\"#9AA5B1\" text-anchor=\"end\">'+fmtK(mx*f)+'</text>';});",
" mo.forEach(function(mi,ix){var c=series[mi]||{};var x0=PL+ix*((W-PL)/mo.length);var bw=((W-PL)/mo.length)-16;var y=H-PB;var bd=(D.seq[mi].y!==D.curY);",
"  names.forEach(function(g){var v=Math.max(0,c[g]||0);if(!v)return;var h=v/mx*(H-PB-14);sv+='<rect x=\"'+x0+'\" y=\"'+(y-h)+'\" width=\"'+bw+'\" height=\"'+h+'\" fill=\"'+colors(g)+'\"><title>'+esc(g)+': '+fmt(v)+'</title></rect>';y-=h;});",
"  sv+='<text x=\"'+(x0+bw/2)+'\" y=\"'+(H-PB+13)+'\" font-size=\"9.5\" font-weight=\"600\" fill=\"'+(bd?'#B45309':'#5F6B7A')+'\" text-anchor=\"middle\">'+mlab(mi)+'</text>';",
"  sv+='<text x=\"'+(x0+bw/2)+'\" y=\"'+(H-PB+24)+'\" font-size=\"8.5\" fill=\"#9AA5B1\" text-anchor=\"middle\">'+fmt(mv[ix])+'</text>';});",
" return '<div style=\"overflow-x:auto\">'+sv+'</svg></div>';}",
"function donut(totals,names,colors){var tot=0;names.forEach(function(g){tot+=Math.max(0,totals[g]||0);});",
" var dsz=170,rr=62,cx=dsz/2,cy=dsz/2,circ=2*Math.PI*rr,off=0,dv='<svg width=\"'+dsz+'\" height=\"'+dsz+'\" viewBox=\"0 0 '+dsz+' '+dsz+'\">';",
" names.forEach(function(g){var v=Math.max(0,totals[g]||0);if(!tot||!v)return;var fr=v/tot;dv+='<circle r=\"'+rr+'\" cx=\"'+cx+'\" cy=\"'+cy+'\" fill=\"transparent\" stroke=\"'+colors(g)+'\" stroke-width=\"26\" stroke-dasharray=\"'+(fr*circ)+' '+circ+'\" stroke-dashoffset=\"'+(-off*circ)+'\" transform=\"rotate(-90 '+cx+' '+cy+')\"><title>'+esc(g)+': '+(fr*100).toFixed(1)+'%</title></circle>';off+=fr;});",
" dv+='<text x=\"'+cx+'\" y=\"'+(cy-2)+'\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"800\" fill=\"#0B2E59\">'+fmt(tot)+'</text><text x=\"'+cx+'\" y=\"'+(cy+14)+'\" text-anchor=\"middle\" font-size=\"9\" fill=\"#9AA5B1\">SAR</text></svg>';return dv;}",
"function hbars(list,vals,color,onclick){var mx=list.length?vals[list[0]]:1,h='';list.forEach(function(n){h+='<div class=\"r'+(onclick?' click':'')+'\"'+(onclick?' onclick=\"'+onclick.replace('%K%',esc(n).replace(/'/g,'&#39;'))+'\"':'')+'><div class=\"n\" title=\"'+esc(n)+'\">'+esc(n)+'</div><div class=\"t\"><div class=\"b\" style=\"width:'+Math.max(2,vals[n]/mx*100)+'%;background:'+color+'\"></div></div><div class=\"v\">'+fmt(vals[n])+'</div></div>';});return h||'<div class=\"note\">no data</div>';}",
"function legend(names,colors,click){var lg='';names.forEach(function(g){lg+='<span'+(click?' onclick=\"goLine(\\''+g+'\\')\"':'')+'><i style=\"background:'+colors(g)+'\"></i>'+g+'</span>';});return '<div class=\"leg\">'+lg+'</div>';}",
