"function acctAgg(filterLine){var mo=months(),am={};for(var i=0;i<D.a3.length;i++){var r=D.a3[i];if(!inDiv(r[0]))continue;if(filterLine&&r[2]!==filterLine)continue;if(mo.indexOf(r[3])<0)continue;var k=(st.div==='ALL'?r[0]+' \\u00b7 ':'')+r[1];if(!am[k])am[k]={t:0,m:{},div:r[0],name:r[1]};am[k].t+=r[4];am[k].m[r[3]]=(am[k].m[r[3]]||0)+r[4];}return am;}",
"// ---- views ----",
"// ---- YoY same-period compare (LY = Jan..today of prev year) ----",
"function lyTotByGroup(){var t={};for(var i=0;i<D.l1.length;i++){var r=D.l1[i];if(!inDiv(r[0]))continue;var g=(st.div==='ALL'?r[0]:r[1]);t[g]=(t[g]||0)+r[3];}return t;}",
"function lyMap(){var m={};for(var i=0;i<D.l1.length;i++){var r=D.l1[i];if(!inDiv(r[0]))continue;var g=(st.div==='ALL'?r[0]:r[1]);m[g+'|'+r[2]]=(m[g+'|'+r[2]]||0)+r[3];}return m;}",
"function acctAggLY(filterLine){var am={};if(!st.cmp)return am;var ms={};months().forEach(function(mi){if(D.seq[mi].y===D.curY)ms[D.seq[mi].m]=1;});",
"for(var i=0;i<D.l3.length;i++){var r=D.l3[i];if(!inDiv(r[0]))continue;if(filterLine&&r[2]!==filterLine)continue;if(!ms[r[3]])continue;var k=(st.div==='ALL'?r[0]+' \\u00b7 ':'')+r[1];am[k]=(am[k]||0)+r[4];}return am;}",
"function yoyBadge(c,l){if(!st.cmp)return '';if(!l)return '<div style=\"font-size:10px;color:#9AA5B1;margin-top:3px\">LY: \\u2014 (new)</div>';var d=100*(c-l)/Math.abs(l);var col=d>=0?'#188038':'#D93025';return '<div style=\"font-size:10px;color:#9AA5B1;margin-top:3px\">LY '+(D.curY-1)+': '+fmt(l)+' <b style=\"color:'+col+'\">'+(d>=0?'+':'')+d.toFixed(1)+'%</b></div>';}",
"function yoyCell(d){return d==null?'<td style=\"color:#9AA5B1\">\\u2014</td>':'<td style=\"font-weight:700;color:'+(d>=0?'#188038':'#D93025')+'\">'+(d>=0?'+':'')+d.toFixed(1)+'%</td>';}",
