"function covColor(c){if(c==null)return '#6B7688';if(c<=6)return '#0A7A3F';if(c<=12)return '#9A6B00';return '#A5241F';}",
"function acctHosp(n){var s=(''+n).toUpperCase();if(/PSMMC/.test(s))return 'PSMMC';if(/MODA|MIN\\.? OF DEF|DEFENSE/.test(s))return 'MODA (Min. of Defense)';if(/KAAUH|PRINCESS NORA/.test(s))return 'Princess Nora / KAAUH';if(/KFSH/.test(s))return 'KFSH';if(/SFH|SECURITY FORCE/.test(s))return 'SFH (Security Forces)';if(/JHAH/.test(s))return 'JHAH';if(/KFMC/.test(s))return 'KFMC';if(/\\bNG\\b|NATIONAL GUARD|KING KHALID/.test(s))return 'National Guard';return null;}",
"function covSales(){var o={};for(var i=0;i<D.a3.length;i++){var r=D.a3[i];if(r[2]!=='GPPRR')continue;if(!D.seq[r[3]]||D.seq[r[3]].y!==D.curY)continue;var hz=acctHosp(r[1]);if(!hz)continue;o[hz]=(o[hz]||0)+r[4];}return o;}",
